fun stretch(input: Int): Int {
    var total = input
    total += 1
    val a = total + 1
    val b = total + 2
    val c = total + 3
    val d = total + 4
    val e = total + 5
    val f = total + 6
    val g = total + 7
    val h = total + 8
    val i = total + 9
    val j = total + 10
    val k = total + 11
    val m = total + 12
    val n = total + 13
    val o = total + 14
    val p = total + 15
    total += a
    return total
}
